-- Carga inicial do guia de acolhimento (RF05), do Guia de Recife (UC40) e dos contatos, cartilhas e aviso de apoio, gerada dos mocks do frontend
-- (data/mockGuides.ts e data/mockGuide.ts). Textos em EN/ES precisam de revisão humana.
-- Onde o mock não tem tradução, a coluna _en/_es fica nula e o aplicativo usa o português.
-- O Guia de Recife existia só em português: a tradução para EN e ES foi sugerida automaticamente e está
-- marcada em machine_translated_langs até uma pessoa revisar (inclui avisos de segurança e horários).
-- Os tópicos 'beneficios' (RU) e 'chegada-transporte' (portaria principal) apontavam para locais que ainda
-- não existem em places (ru, portaria-principal); entram com place_id nulo até esses locais serem cadastrados.
-- Contatos, cartilhas e aviso de apoio: tabelas criadas na migration anterior (guia_contatos_downloads_e_apoio).
-- Não repetir: slugs são únicos e uma segunda execução falha.

insert into public.guide_topics
  (slug, section, stage, title_pt, title_en, title_es, summary_pt, summary_en, summary_es,
   blocks_pt, blocks_en, blocks_es, links_pt, links_en, links_es, source_pt, source_en, source_es, place_id, position)
values
  ('boas-vindas', 'cultura', null, 'Bem-vindo(a) à Ruralinda', 'Welcome to Ruralinda', 'Bienvenido(a) a la Ruralinda', 'Por que esta cartilha existe e o que esperar dos primeiros meses no Brasil.', 'Why this booklet exists and what to expect in your first months in Brazil.', 'Por qué existe esta cartilla y qué esperar de los primeros meses en Brasil.', '[{"type":"p","text":"Seja muito bem-vindo(a) ao Brasil e à Universidade Federal Rural de Pernambuco (UFRPE), nossa Ruralinda! Esta cartilha foi elaborada para orientá-lo(a) durante seus primeiros meses de estadia no país."},{"type":"p","text":"O Brasil é um país vasto, diverso e vibrante, mas, como em qualquer lugar do mundo, possui leis e costumes próprios que podem ser diferentes dos do seu país. Nosso objetivo é garantir que sua estadia seja segura, produtiva e repleta de boas trocas culturais."},{"type":"callout","tone":"tip","title":"O choque cultural é normal","text":"A integração é um processo recompensador. Explore, pergunte, participe dos eventos e permita-se vivenciar o melhor que o Brasil e a universidade têm a oferecer."}]'::jsonb, '[{"type":"p","text":"Welcome to Brazil and to the Federal Rural University of Pernambuco (UFRPE), our Ruralinda! This booklet was prepared to guide you during your first months in the country."},{"type":"p","text":"Brazil is a vast, diverse and vibrant country but, like anywhere in the world, it has its own laws and customs that may differ from those of your country. Our goal is to make sure your stay is safe, productive and full of good cultural exchanges."},{"type":"callout","tone":"tip","title":"Culture shock is normal","text":"Integration is a rewarding process. Explore, ask questions, take part in events and allow yourself to experience the best Brazil and the university have to offer."}]'::jsonb, '[{"type":"p","text":"¡Bienvenido(a) a Brasil y a la Universidad Federal Rural de Pernambuco (UFRPE), nuestra Ruralinda! Esta cartilla fue elaborada para orientarte durante tus primeros meses en el país."},{"type":"p","text":"Brasil es un país vasto, diverso y vibrante, pero, como en cualquier lugar del mundo, tiene leyes y costumbres propias que pueden ser diferentes de las de tu país. Nuestro objetivo es que tu estadía sea segura, productiva y llena de buenos intercambios culturales."},{"type":"callout","tone":"tip","title":"El choque cultural es normal","text":"La integración es un proceso gratificante. Explora, pregunta, participa en los eventos y permítete vivir lo mejor que Brasil y la universidad ofrecen."}]'::jsonb, '[{"label":"Portal internacional da UFRPE","url":"https://international.ufrpe.br"}]'::jsonb, '[{"label":"UFRPE international portal","url":"https://international.ufrpe.br"}]'::jsonb, '[{"label":"Portal internacional de la UFRPE","url":"https://international.ufrpe.br"}]'::jsonb, 'Cartilha de Acolhimento · NINTER/PRPG UFRPE', 'Welcome Booklet · NINTER/PRPG UFRPE', 'Cartilla de Acogida · NINTER/PRPG UFRPE', null, 0),
  ('convivencia', 'cultura', null, 'Princípios de convivência', 'Principles of coexistence', 'Principios de convivencia', 'Respeito à diversidade e por que discriminação é crime no Brasil.', 'Respect for diversity and why discrimination is a crime in Brazil.', 'Respeto a la diversidad y por qué la discriminación es delito en Brasil.', '[{"type":"p","text":"O Brasil é um dos países mais diversos do mundo. Nossa força está na mistura de raças, religiões, culturas e identidades. A base da nossa convivência é a empatia: independentemente de origem, crença ou orientação, todos têm o direito de se sentir seguros e respeitados."},{"type":"heading","text":"É fundamental"},{"type":"list","items":["respeitar as diferenças culturais, religiosas e linguísticas;","evitar comentários preconceituosos ou discriminatórios;","valorizar o diálogo e a convivência pacífica;","tratar todas as pessoas com cordialidade e igualdade."]},{"type":"callout","tone":"warning","title":"Discriminação é crime!","text":"Racismo e qualquer forma de discriminação baseada em procedência nacional, cor da pele, orientação sexual, etnia ou religião são proibidos por lei e podem gerar consequências acadêmicas e legais. Brincadeiras sobre cor da pele, sotaque ou religião de alguém não são aceitas."}]'::jsonb, '[{"type":"p","text":"Brazil is one of the most diverse countries in the world. Our strength lies in the mix of races, religions, cultures and identities. Empathy is the basis of our coexistence: regardless of origin, belief or orientation, everyone has the right to feel safe and respected."},{"type":"heading","text":"It is essential to"},{"type":"list","items":["respect cultural, religious and linguistic differences;","avoid prejudiced or discriminatory remarks;","value dialogue and peaceful coexistence;","treat everyone with courtesy and equality."]},{"type":"callout","tone":"warning","title":"Discrimination is a crime!","text":"Racism and any form of discrimination based on national origin, skin colour, sexual orientation, ethnicity or religion are prohibited by law and may lead to academic and legal consequences. Jokes about someone''s skin colour, accent or religion are not accepted."}]'::jsonb, '[{"type":"p","text":"O Brasil é um dos países mais diversos do mundo. Nossa força está na mistura de raças, religiões, culturas e identidades. A base da nossa convivência é a empatia: independentemente de origem, crença ou orientação, todos têm o direito de se sentir seguros e respeitados."},{"type":"heading","text":"Es fundamental"},{"type":"list","items":["respeitar as diferenças culturais, religiosas e linguísticas;","evitar comentários preconceituosos ou discriminatórios;","valorizar o diálogo e a convivência pacífica;","tratar todas as pessoas com cordialidade e igualdade."]},{"type":"callout","tone":"warning","title":"¡La discriminación es delito!","text":"Racismo e qualquer forma de discriminação baseada em procedência nacional, cor da pele, orientação sexual, etnia ou religião são proibidos por lei e podem gerar consequências acadêmicas e legais. Brincadeiras sobre cor da pele, sotaque ou religião de alguém não são aceitas."}]'::jsonb, '[]'::jsonb, null, null, 'Cartilha de Acolhimento · NINTER/PRPG UFRPE', 'Welcome Booklet · NINTER/PRPG UFRPE', 'Cartilla de Acogida · NINTER/PRPG UFRPE', null, 1),
  ('comunicacao', 'cultura', null, 'Comunicação e cultura brasileira', 'Communication and Brazilian culture', 'Comunicación y cultura brasileña', 'Cumprimentos, “jeitinho brasileiro”, convites e pontualidade.', 'Greetings, the “Brazilian way”, invitations and punctuality.', 'Saludos, el “jeitinho brasileño”, invitaciones y puntualidad.', '[{"type":"p","text":"Os brasileiros valorizam muito o “bom dia”, o “por favor” e o “obrigado”. Esses pequenos gestos abrem portas: cumprimente ao chegar e sair, use “com licença”, respeite filas e espaços compartilhados."},{"type":"facts","items":[{"label":"Cumprimentos","value":"Aperto de mão, abraço ou beijo no rosto (um ou dois, conforme a região). Se não se sentir confortável, um sorriso e um aceno são sempre bem aceitos."},{"label":"“Jeitinho brasileiro”","value":"No social, é visto como flexibilidade. Em provas, prazos e documentos ele não se aplica: as regras da UFRPE devem ser rigorosamente respeitadas."},{"label":"Pontualidade","value":"No meio acadêmico, seja pontual: atrasos em aulas e provas podem não ser tolerados. Em festas, chegar um pouco depois do horário é o padrão."},{"label":"“Vamos marcar!”","value":"Nem sempre é um compromisso agendado — muitas vezes é só um gesto de simpatia."}]},{"type":"callout","tone":"info","text":"O idioma oficial do Brasil é o português. Aprender expressões básicas facilita muito sua adaptação — a UFRPE oferece cursos de Português como Língua Estrangeira todo semestre."}]'::jsonb, '[{"type":"p","text":"Brazilians greatly value “bom dia” (good morning), “por favor” (please) and “obrigado” (thank you). These small gestures open doors: greet people when arriving and leaving, say “com licença” (excuse me), respect queues and shared spaces."},{"type":"facts","items":[{"label":"Greetings","value":"Handshake, hug or kiss on the cheek (one or two, depending on the region). If you''re not comfortable, a smile and a wave are always fine."},{"label":"The “Brazilian way”","value":"Socially, it is seen as flexibility. For exams, deadlines and documents it doesn''t apply: UFRPE rules must be strictly followed."},{"label":"Punctuality","value":"In academic settings, be on time: being late for classes and exams may not be tolerated. At parties, arriving a little late is the norm."},{"label":"“Let''s meet up!”","value":"It isn''t always a scheduled commitment — often it''s just a friendly gesture."}]},{"type":"callout","tone":"info","text":"Brazil''s official language is Portuguese. Learning basic expressions makes adapting much easier — UFRPE offers Portuguese as a Foreign Language courses every semester."}]'::jsonb, '[{"type":"p","text":"Os brasileiros valorizam muito o “bom dia”, o “por favor” e o “obrigado”. Esses pequenos gestos abrem portas: cumprimente ao chegar e sair, use “com licença”, respeite filas e espaços compartilhados."},{"type":"facts","items":[{"label":"Saludos","value":"Aperto de mão, abraço ou beijo no rosto (um ou dois, conforme a região). Se não se sentir confortável, um sorriso e um aceno são sempre bem aceitos."},{"label":"“Jeitinho brasileño”","value":"No social, é visto como flexibilidade. Em provas, prazos e documentos ele não se aplica: as regras da UFRPE devem ser rigorosamente respeitadas."},{"label":"Puntualidad","value":"No meio acadêmico, seja pontual: atrasos em aulas e provas podem não ser tolerados. Em festas, chegar um pouco depois do horário é o padrão."},{"label":"“¡Vamos a quedar!”","value":"Nem sempre é um compromisso agendado — muitas vezes é só um gesto de simpatia."}]},{"type":"callout","tone":"info","text":"O idioma oficial do Brasil é o português. Aprender expressões básicas facilita muito sua adaptação — a UFRPE oferece cursos de Português como Língua Estrangeira todo semestre."}]'::jsonb, '[]'::jsonb, null, null, 'Cartilha de Acolhimento · NINTER/PRPG UFRPE', 'Welcome Booklet · NINTER/PRPG UFRPE', 'Cartilla de Acogida · NINTER/PRPG UFRPE', null, 2),
  ('consentimento', 'cultura', null, 'Assédio, consentimento e substâncias', 'Harassment, consent and substances', 'Acoso, consentimiento y sustancias', 'Limites pessoais, álcool e drogas segundo a lei brasileira.', 'Personal boundaries, alcohol and drugs under Brazilian law.', 'Límites personales, alcohol y drogas según la ley brasileña.', '[{"type":"p","text":"No Brasil, as interações sociais costumam ser cordiais. É preciso diferenciar um gesto de educação e acolhimento daquilo que representa intimidade ou abertura para ultrapassar limites. Evite comentários, gestos ou abordagens invasivos."},{"type":"callout","tone":"warning","title":"“Não” significa “não”","text":"Vale para interações físicas e verbais. O assédio sexual ou moral pode levar à expulsão da universidade e a processos criminais."},{"type":"facts","items":[{"label":"Álcool","value":"Permitido apenas para maiores de 18 anos. É proibido dirigir após consumir qualquer quantidade."},{"label":"Drogas","value":"Porte e comercialização de drogas ilícitas são crimes, com consequências acadêmicas, administrativas e legais."}]}]'::jsonb, '[{"type":"p","text":"In Brazil, social interactions tend to be warm. It''s important to tell a gesture of politeness and welcome apart from something that signals intimacy or openness to cross boundaries. Avoid invasive comments, gestures or approaches."},{"type":"callout","tone":"warning","title":"“No” means “no”","text":"This applies to physical and verbal interactions. Sexual or moral harassment may lead to expulsion from the university and criminal charges."},{"type":"facts","items":[{"label":"Alcohol","value":"Allowed only for people aged 18 or over. Driving after drinking any amount is forbidden."},{"label":"Drugs","value":"Possession and trafficking of illegal drugs are crimes, with academic, administrative and legal consequences."}]}]'::jsonb, '[{"type":"p","text":"No Brasil, as interações sociais costumam ser cordiais. É preciso diferenciar um gesto de educação e acolhimento daquilo que representa intimidade ou abertura para ultrapassar limites. Evite comentários, gestos ou abordagens invasivos."},{"type":"callout","tone":"warning","title":"“No” significa “no”","text":"Vale para interações físicas e verbais. O assédio sexual ou moral pode levar à expulsão da universidade e a processos criminais."},{"type":"facts","items":[{"label":"Alcohol","value":"Permitido apenas para maiores de 18 anos. É proibido dirigir após consumir qualquer quantidade."},{"label":"Drogas","value":"Porte e comercialização de drogas ilícitas são crimes, com consequências acadêmicas, administrativas e legais."}]}]'::jsonb, '[]'::jsonb, null, null, 'Cartilha de Acolhimento · NINTER/PRPG UFRPE', 'Welcome Booklet · NINTER/PRPG UFRPE', 'Cartilla de Acogida · NINTER/PRPG UFRPE', null, 3),
  ('vida-academica', 'cultura', null, 'Convivência acadêmica e moradia', 'Academic life and shared housing', 'Convivencia académica y vivienda', 'Relação com professores, servidores, colegas e espaços compartilhados.', 'Relationships with professors, staff, classmates and shared spaces.', 'Relación con profesores, servidores, compañeros y espacios compartidos.', '[{"type":"heading","text":"Na universidade, espera-se"},{"type":"list","items":["pontualidade em aulas, reuniões e atividades;","honestidade intelectual, evitando plágio e fraude acadêmica;","uso adequado dos espaços institucionais;","respeito a professores, colegas, servidores técnico-administrativos e terceirizados."]},{"type":"p","text":"A relação com professores costuma ser menos rígida do que em outros países, mas isso não exclui o respeito. Eles geralmente são chamados pelo primeiro nome, precedido de “professor(a)”."},{"type":"heading","text":"Em moradias e espaços compartilhados"},{"type":"list","items":["respeite horários de silêncio e evite barulhos excessivos;","mantenha limpeza e organização e cuide dos bens compartilhados;","economize água e energia e faça o descarte adequado do lixo."]}]'::jsonb, '[{"type":"heading","text":"At the university, you are expected to"},{"type":"list","items":["be punctual for classes, meetings and activities;","be intellectually honest, avoiding plagiarism and academic fraud;","use institutional spaces properly;","respect professors, classmates, administrative and outsourced staff."]},{"type":"p","text":"Relationships with professors tend to be less formal than in other countries, but respect is still expected. They are usually addressed by first name, preceded by “professor”."},{"type":"heading","text":"In shared housing and common spaces"},{"type":"list","items":["respect quiet hours and avoid excessive noise;","keep spaces clean and organised and take care of shared belongings;","save water and energy and dispose of waste properly."]}]'::jsonb, '[{"type":"heading","text":"En la universidad se espera"},{"type":"list","items":["pontualidade em aulas, reuniões e atividades;","honestidade intelectual, evitando plágio e fraude acadêmica;","uso adequado dos espaços institucionais;","respeito a professores, colegas, servidores técnico-administrativos e terceirizados."]},{"type":"p","text":"A relação com professores costuma ser menos rígida do que em outros países, mas isso não exclui o respeito. Eles geralmente são chamados pelo primeiro nome, precedido de “professor(a)”."},{"type":"heading","text":"En viviendas y espacios compartidos"},{"type":"list","items":["respeite horários de silêncio e evite barulhos excessivos;","mantenha limpeza e organização e cuide dos bens compartilhados;","economize água e energia e faça o descarte adequado do lixo."]}]'::jsonb, '[]'::jsonb, null, null, 'Cartilha de Acolhimento · NINTER/PRPG UFRPE', 'Welcome Booklet · NINTER/PRPG UFRPE', 'Cartilla de Acogida · NINTER/PRPG UFRPE', null, 4),
  ('conflitos', 'cultura', null, 'Conflitos e onde buscar ajuda', 'Conflicts and where to get help', 'Conflictos y dónde buscar ayuda', 'Como lidar com situações sensíveis e quais as consequências de condutas inadequadas.', 'How to handle sensitive situations and the consequences of inappropriate conduct.', 'Cómo manejar situaciones sensibles y las consecuencias de conductas inadecuadas.', '[{"type":"steps","items":[{"title":"Mantenha a calma","text":"O tom de voz alto no Brasil nem sempre significa agressividade; às vezes é apenas entusiasmo. Tente resolver mal-entendidos com uma conversa calma e direta."},{"title":"Evite discussões ofensivas","text":"Política, religião e futebol podem gerar debates acalorados. É perfeitamente aceitável retirar-se de uma conversa desrespeitosa."},{"title":"Procure mediação","text":"Se não conseguir resolver sozinho(a), procure o NINTER, a Coordenação de Internacionalização ou a coordenação do seu curso. Não tente resolver situações graves por conta própria."}]},{"type":"callout","tone":"warning","title":"Consequências reais","text":"Plágio, assédio ou vandalismo podem resultar em advertência, suspensão ou expulsão — o que pode invalidar o visto de estudante. Crimes do Código Penal podem levar a multa, prisão e deportação."},{"type":"p","text":"Você não está sozinho(a)! Em caso de dúvida sobre normas acadêmicas, migratórias ou da vida cotidiana, procure os setores de internacionalização da UFRPE antes de tomar qualquer decisão. Os contatos estão no quadro “Precisa de ajuda?”."}]'::jsonb, '[{"type":"steps","items":[{"title":"Stay calm","text":"A raised voice in Brazil doesn''t always mean aggression; sometimes it''s just enthusiasm. Try to clear up misunderstandings through calm, direct conversation."},{"title":"Avoid offensive arguments","text":"Politics, religion and football can lead to heated debates. It''s perfectly acceptable to step away from a disrespectful conversation."},{"title":"Seek mediation","text":"If you can''t solve it on your own, contact NINTER, the Internationalization Coordination or your program coordinator. Don''t handle serious situations alone."}]},{"type":"callout","tone":"warning","title":"Real consequences","text":"Plagiarism, harassment or vandalism may lead to warnings, suspension or expulsion — which may invalidate your student visa. Crimes under the Penal Code may lead to fines, imprisonment and deportation."},{"type":"p","text":"You are not alone! If you have questions about academic or immigration rules or everyday life, contact UFRPE''s internationalization offices before making any decision. Contacts are in the “Need help?” box."}]'::jsonb, '[{"type":"steps","items":[{"title":"Mantén la calma","text":"O tom de voz alto no Brasil nem sempre significa agressividade; às vezes é apenas entusiasmo. Tente resolver mal-entendidos com uma conversa calma e direta."},{"title":"Evita discusiones ofensivas","text":"Política, religião e futebol podem gerar debates acalorados. É perfeitamente aceitável retirar-se de uma conversa desrespeitosa."},{"title":"Busca mediación","text":"Se não conseguir resolver sozinho(a), procure o NINTER, a Coordenação de Internacionalização ou a coordenação do seu curso. Não tente resolver situações graves por conta própria."}]},{"type":"callout","tone":"warning","title":"Consecuencias reales","text":"Plágio, assédio ou vandalismo podem resultar em advertência, suspensão ou expulsão — o que pode invalidar o visto de estudante. Crimes do Código Penal podem levar a multa, prisão e deportação."},{"type":"p","text":"Você não está sozinho(a)! Em caso de dúvida sobre normas acadêmicas, migratórias ou da vida cotidiana, procure os setores de internacionalização da UFRPE antes de tomar qualquer decisão. Os contatos estão no quadro “Precisa de ajuda?”."}]'::jsonb, '[{"label":"Portal internacional da UFRPE","url":"https://international.ufrpe.br"}]'::jsonb, '[{"label":"UFRPE international portal","url":"https://international.ufrpe.br"}]'::jsonb, '[{"label":"Portal internacional de la UFRPE","url":"https://international.ufrpe.br"}]'::jsonb, 'Cartilha de Acolhimento · NINTER/PRPG UFRPE', 'Welcome Booklet · NINTER/PRPG UFRPE', 'Cartilla de Acogida · NINTER/PRPG UFRPE', (select id from public.places where slug = 'reitoria'), 5),
  ('visto', 'documentos', 'antes', 'Visto de estudante (VITEM IV)', 'Student visa (VITEM IV)', 'Visa de estudiante (VITEM IV)', 'Documentos para pedir o visto no Consulado brasileiro antes de viajar.', 'Documents to apply for the visa at the Brazilian Consulate before travelling.', 'Documentos para solicitar la visa en el Consulado brasileño antes de viajar.', '[{"type":"p","text":"O VITEM IV é o visto temporário para estrangeiros que vão estudar em instituições reconhecidas pelo MEC. O pedido é feito presencialmente na Repartição Consular brasileira do seu país."},{"type":"checklist","id":"visto","title":"Leve ao Consulado","items":["Formulário de pedido de visto impresso e assinado","Carta de aceitação original da UFRPE","Passaporte válido por 6 meses ou mais (e comprovante de filiação, se não constar)","Foto 3x4 recente, de frente, fundo branco","Comprovante de pagamento da taxa consular","Comprovação de meios de subsistência (bolsa, termo de responsabilidade ou extrato)","Certidão de antecedentes criminais emitida há menos de 3 meses","Comprovante de vínculo com a instituição de origem","Autorização dos pais com firma reconhecida (se menor de idade)"]},{"type":"callout","tone":"info","text":"A lista pode variar conforme o Consulado do seu país. Confirme diretamente com ele antes de agendar."}]'::jsonb, '[{"type":"p","text":"VITEM IV is the temporary visa for foreigners who will study at institutions recognised by Brazil''s Ministry of Education. You apply in person at the Brazilian Consulate in your country."},{"type":"checklist","id":"visto","title":"Bring to the Consulate","items":["Visa application form, printed and signed","Original UFRPE acceptance letter","Passport valid for 6+ months (plus proof of parentage if not shown)","Recent 3x4 photo, front-facing, white background","Proof of consular fee payment","Proof of means of support (scholarship, sponsorship letter or bank statement)","Criminal record certificate issued less than 3 months ago","Proof of enrolment at your home institution","Notarised parental authorisation (if under 18)"]},{"type":"callout","tone":"info","text":"The list may vary by Consulate. Confirm directly with yours before booking."}]'::jsonb, '[{"type":"p","text":"O VITEM IV é o visto temporário para estrangeiros que vão estudar em instituições reconhecidas pelo MEC. O pedido é feito presencialmente na Repartição Consular brasileira do seu país."},{"type":"checklist","id":"visto","title":"Lleva al Consulado","items":["Formulário de pedido de visto impresso e assinado","Carta de aceitação original da UFRPE","Passaporte válido por 6 meses ou mais (e comprovante de filiação, se não constar)","Foto 3x4 recente, de frente, fundo branco","Comprovante de pagamento da taxa consular","Comprovação de meios de subsistência (bolsa, termo de responsabilidade ou extrato)","Certidão de antecedentes criminais emitida há menos de 3 meses","Comprovante de vínculo com a instituição de origem","Autorização dos pais com firma reconhecida (se menor de idade)"]},{"type":"callout","tone":"info","text":"A lista pode variar conforme o Consulado do seu país. Confirme diretamente com ele antes de agendar."}]'::jsonb, '[{"label":"Formulário de candidatura do estudante estrangeiro","url":"https://docs.google.com/forms/d/1CJAgP-p6goCS-R23pYx1e7EBrDXN2D6b4bTJ6P7Tpq8/viewform"}]'::jsonb, '[{"label":"Exchange student application form","url":"https://docs.google.com/forms/d/1CJAgP-p6goCS-R23pYx1e7EBrDXN2D6b4bTJ6P7Tpq8/viewform"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 0),
  ('seguro-saude', 'documentos', 'antes', 'Seguro saúde', 'Health insurance', 'Seguro de salud', 'Obrigatório durante toda a permanência no Brasil.', 'Mandatory for your entire stay in Brazil.', 'Obligatorio durante toda la estadía en Brasil.', '[{"type":"p","text":"O estudante internacional deve ter um seguro saúde válido durante toda a permanência no Brasil. Ele garante atendimento em hospitais particulares, o cumprimento das leis de imigração e evita despesas médicas inesperadas. A lei exige seguro com repatriação funerária para vistos de trânsito, turista e temporário."},{"type":"callout","tone":"tip","text":"Chegou sem seguro? Será preciso contratar um em uma agência local logo nos primeiros dias."}]'::jsonb, '[{"type":"p","text":"International students must have valid health insurance for their entire stay in Brazil. It covers private hospitals, ensures compliance with immigration law and avoids unexpected medical costs. The law requires insurance with funeral repatriation for transit, tourist and temporary visas."},{"type":"callout","tone":"tip","text":"Arrived without insurance? You''ll need to buy one from a local agency in your first days."}]'::jsonb, null, '[]'::jsonb, null, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 1),
  ('cpf', 'documentos', 'antes', 'CPF', 'CPF (Brazilian taxpayer ID)', 'CPF', 'Necessário para conta bancária, chip de celular, Wi-Fi e biblioteca. Pode ser tirado ainda no seu país.', 'Needed for a bank account, SIM card, Wi-Fi and the library. You can get it in your home country.', 'Necesario para cuenta bancaria, chip de celular, Wi-Fi y biblioteca. Se puede tramitar en tu país.', '[{"type":"facts","items":[{"label":"Onde","value":"Site da Receita Federal + Consulado brasileiro"},{"label":"Prazo de emissão","value":"Até 1 dia útil após a entrega no Consulado"},{"label":"Custo","value":"Gratuito"}]},{"type":"steps","items":[{"title":"Preencha o formulário online","text":"No site da Receita Federal, escolha o país de domicílio, marque “inscrição”, preencha e envie. Imprima o comprovante ou anote o número de protocolo."},{"title":"Vá ao Consulado brasileiro","text":"Apresente o protocolo com cópia de um documento que comprove identidade, nacionalidade, naturalidade e data de nascimento. Entre 18 e 70 anos, leve também o documento da Justiça Eleitoral sobre alistamento eleitoral."},{"title":"Receba o número do CPF","text":"O Consulado processa o pedido e emite o CPF em até um dia útil."}]},{"type":"callout","tone":"warning","title":"Dados errados?","text":"A correção é gratuita no Consulado em até 90 dias. Depois disso, só a Receita Federal no Brasil pode alterar."}]'::jsonb, '[{"type":"facts","items":[{"label":"Where","value":"Federal Revenue website + Brazilian Consulate"},{"label":"Issuing time","value":"Up to 1 business day after submitting at the Consulate"},{"label":"Cost","value":"Free"}]},{"type":"steps","items":[{"title":"Fill in the online form","text":"On the Federal Revenue website, choose your country of residence, select “inscrição” (registration), fill in and submit. Print the receipt or write down the protocol number."},{"title":"Go to the Brazilian Consulate","text":"Present the protocol with a copy of an ID proving identity, nationality, place and date of birth. If aged 18–70, also bring the electoral document regarding voter registration."},{"title":"Receive your CPF number","text":"The Consulate processes the request and issues the CPF within one business day."}]},{"type":"callout","tone":"warning","title":"Wrong details?","text":"Corrections are free at the Consulate within 90 days. After that, only the Federal Revenue in Brazil can change them."}]'::jsonb, '[{"type":"facts","items":[{"label":"Dónde","value":"Site da Receita Federal + Consulado brasileiro"},{"label":"Plazo","value":"Até 1 dia útil após a entrega no Consulado"},{"label":"Costo","value":"Gratuito"}]},{"type":"steps","items":[{"title":"Completa el formulario en línea","text":"No site da Receita Federal, escolha o país de domicílio, marque “inscrição”, preencha e envie. Imprima o comprovante ou anote o número de protocolo."},{"title":"Ve al Consulado brasileño","text":"Apresente o protocolo com cópia de um documento que comprove identidade, nacionalidade, naturalidade e data de nascimento. Entre 18 e 70 anos, leve também o documento da Justiça Eleitoral sobre alistamento eleitoral."},{"title":"Recibe tu número de CPF","text":"O Consulado processa o pedido e emite o CPF em até um dia útil."}]},{"type":"callout","tone":"warning","title":"¿Datos incorrectos?","text":"A correção é gratuita no Consulado em até 90 dias. Depois disso, só a Receita Federal no Brasil pode alterar."}]'::jsonb, '[{"label":"Receita Federal — inscrição de CPF para estrangeiros","url":"https://servicos.receita.fazenda.gov.br/Servicos/CPF/InscricaoCpfEstrangeiro/default.asp"}]'::jsonb, '[{"label":"Federal Revenue — CPF registration for foreigners","url":"https://servicos.receita.fazenda.gov.br/Servicos/CPF/InscricaoCpfEstrangeiro/default.asp"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 2),
  ('crnm', 'documentos', 'chegada', 'Registro migratório (CRNM)', 'Migration registration (CRNM)', 'Registro migratorio (CRNM)', 'Registro na Polícia Federal em até 30 dias após a chegada.', 'Register with the Federal Police within 30 days of arrival.', 'Registro en la Policía Federal hasta 30 días después de la llegada.', '[{"type":"facts","items":[{"label":"Prazo","value":"Até 30 dias após a chegada — multa por dia de atraso"},{"label":"Onde","value":"Polícia Federal no Aeroporto do Recife, das 9h às 15h"},{"label":"Contato","value":"(81) 3322-4950 / 4951 / 4948 · estrangeiros@dpf.gov.br"}]},{"type":"steps","items":[{"title":"Guarde o documento de entrada","text":"No voo você recebe um formulário de entrada, que é apresentado à Polícia Federal no desembarque. Ele registra sua chegada e é usado depois para legalizar a permanência."},{"title":"Agende e compareça à Polícia Federal","text":"O registro e a emissão da Carteira de Registro Nacional Migratório (CRNM) são presenciais. Leve passaporte com visto e a carta de aceitação da UFRPE."},{"title":"Acompanhe a validade","text":"A PF define o prazo de estada. Para ficar mais tempo, peça a prorrogação até 30 dias antes do vencimento da CRNM."}]}]'::jsonb, '[{"type":"facts","items":[{"label":"Deadline","value":"Within 30 days of arrival — daily fine if late"},{"label":"Where","value":"Federal Police at Recife Airport, 9am–3pm"},{"label":"Contact","value":"(81) 3322-4950 / 4951 / 4948 · estrangeiros@dpf.gov.br"}]},{"type":"steps","items":[{"title":"Keep your entry document","text":"On the flight you''ll get an entry form to present to the Federal Police on arrival. It records your arrival and is later used to legalise your stay."},{"title":"Book and attend the Federal Police","text":"Registration and issuing of the National Migration Registry Card (CRNM) are done in person. Bring your passport with visa and the UFRPE acceptance letter."},{"title":"Track the expiry date","text":"The Federal Police sets your length of stay. To stay longer, request an extension up to 30 days before your CRNM expires."}]}]'::jsonb, '[{"type":"facts","items":[{"label":"Plazo","value":"Até 30 dias após a chegada — multa por dia de atraso"},{"label":"Dónde","value":"Polícia Federal no Aeroporto do Recife, das 9h às 15h"},{"label":"Contacto","value":"(81) 3322-4950 / 4951 / 4948 · estrangeiros@dpf.gov.br"}]},{"type":"steps","items":[{"title":"Guarda el documento de entrada","text":"No voo você recebe um formulário de entrada, que é apresentado à Polícia Federal no desembarque. Ele registra sua chegada e é usado depois para legalizar a permanência."},{"title":"Agenda y acude a la Policía Federal","text":"O registro e a emissão da Carteira de Registro Nacional Migratório (CRNM) são presenciais. Leve passaporte com visto e a carta de aceitação da UFRPE."},{"title":"Controla la validez","text":"A PF define o prazo de estada. Para ficar mais tempo, peça a prorrogação até 30 dias antes do vencimento da CRNM."}]}]'::jsonb, '[{"label":"Polícia Federal — Imigração","url":"https://www.gov.br/pf/pt-br/assuntos/imigracao"}]'::jsonb, '[{"label":"Federal Police — Immigration","url":"https://www.gov.br/pf/pt-br/assuntos/imigracao"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 3),
  ('carteira-vem', 'documentos', 'primeiras-semanas', 'Carteira de estudante e cartão VEM', 'Student ID card and VEM transit card', 'Carné de estudiante y tarjeta VEM', 'Meia-entrada e passagem de ônibus com desconto em Recife.', 'Half-price tickets and discounted bus fares in Recife.', 'Media entrada y pasaje de autobús con descuento en Recife.', '[{"type":"heading","text":"Carteira de estudante"},{"type":"p","text":"Garante meia-entrada em cinemas, teatros e shows e é obrigatória para o VEM estudante. No início de cada semestre, entidades emitem a carteira nos centros acadêmicos da UFRPE. Taxa entre R$ 22 e R$ 40."},{"type":"checklist","id":"carteira","title":"Para a carteira de estudante","items":["Foto 3x4","Comprovante de matrícula","Passaporte (cópia da identificação e do visto) ou CPF"]},{"type":"heading","text":"Cartão VEM estudante"},{"type":"steps","items":[{"title":"Peça pelo VEM Posto Virtual (site ou app)","text":"Informe e-mail e CPF."},{"title":"Valide o e-mail e agende a retirada"},{"title":"Retire o cartão com os documentos","text":"Passaporte, CPF, comprovante de endereço e comprovante de matrícula."}]},{"type":"callout","tone":"tip","text":"Recarregue pela internet, em aplicativos, estações de BRT, terminais integrados ou na Central VEM (Rua das Ninfas, 278 – Boa Vista, 7h–17h em dias úteis)."}]'::jsonb, '[{"type":"heading","text":"Student ID card"},{"type":"p","text":"Gives half-price entry to cinemas, theatres and concerts and is required for the student VEM card. At the start of each semester, organisations issue it at UFRPE''s student centres. Fee between R$22 and R$40."},{"type":"checklist","id":"carteira","title":"For the student ID card","items":["3x4 photo","Proof of enrolment","Passport (copy of ID page and visa) or CPF"]},{"type":"heading","text":"Student VEM card"},{"type":"steps","items":[{"title":"Apply via VEM Posto Virtual (website or app)","text":"Provide your email and CPF."},{"title":"Validate your email and book a pickup"},{"title":"Pick up the card with your documents","text":"Passport, CPF, proof of address and proof of enrolment."}]},{"type":"callout","tone":"tip","text":"Top up online, via apps, at BRT stations, integrated terminals or at Central VEM (Rua das Ninfas, 278 – Boa Vista, 7am–5pm on weekdays)."}]'::jsonb, '[{"type":"heading","text":"Carné de estudiante"},{"type":"p","text":"Garante meia-entrada em cinemas, teatros e shows e é obrigatória para o VEM estudante. No início de cada semestre, entidades emitem a carteira nos centros acadêmicos da UFRPE. Taxa entre R$ 22 e R$ 40."},{"type":"checklist","id":"carteira","title":"Para el carné de estudiante","items":["Foto 3x4","Comprovante de matrícula","Passaporte (cópia da identificação e do visto) ou CPF"]},{"type":"heading","text":"Tarjeta VEM estudiante"},{"type":"steps","items":[{"title":"Peça pelo VEM Posto Virtual (site ou app)","text":"Informe e-mail e CPF."},{"title":"Valide o e-mail e agende a retirada"},{"title":"Retire o cartão com os documentos","text":"Passaporte, CPF, comprovante de endereço e comprovante de matrícula."}]},{"type":"callout","tone":"tip","text":"Recarregue pela internet, em aplicativos, estações de BRT, terminais integrados ou na Central VEM (Rua das Ninfas, 278 – Boa Vista, 7h–17h em dias úteis)."}]'::jsonb, '[{"label":"Documento do Estudante (UNE)","url":"https://www.documentodoestudante.com.br"},{"label":"Meia-entrada (UEP)","url":"https://www.meiaentradaestudantil.com.br/uep"},{"label":"VEM Posto Virtual","url":"https://vempostovirtual.vemgranderecife.com.br/institucional"}]'::jsonb, '[{"label":"Student ID (UNE)","url":"https://www.documentodoestudante.com.br"},{"label":"Half-price card (UEP)","url":"https://www.meiaentradaestudantil.com.br/uep"},{"label":"VEM Posto Virtual","url":"https://vempostovirtual.vemgranderecife.com.br/institucional"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 4),
  ('banco-celular-moradia', 'documentos', 'primeiras-semanas', 'Conta bancária, celular e aluguel', 'Bank account, phone and renting', 'Cuenta bancaria, celular y alquiler', 'O que levar para abrir conta, ativar um chip e alugar um imóvel.', 'What to bring to open an account, activate a SIM card and rent a home.', 'Qué llevar para abrir una cuenta, activar un chip y alquilar una vivienda.', '[{"type":"checklist","id":"banco","title":"Abrir conta bancária","items":["CPF","Comprovante de residência","Comprovante de renda (bolsa, por exemplo)","Visto temporário ou permanente","Passaporte ou CRNM (ou protocolo do pedido)"]},{"type":"callout","tone":"info","title":"Chip de celular","text":"A linha só é ativada com CPF. As operadoras principais são Vivo, Claro e Tim, com lojas nos shoppings. Para falar com o exterior, prefira aplicativos de mensagem. Código do Brasil: +55; Pernambuco: 81."},{"type":"checklist","id":"aluguel","title":"Alugar um imóvel","items":["Passaporte válido","CRNM","Visto de residência ou de trabalho","Comprovante de renda (alguns proprietários pedem)"]},{"type":"p","text":"Bairros residenciais próximos à UFRPE: Dois Irmãos, Várzea, Caxangá, Iputinga e Apipucos."}]'::jsonb, '[{"type":"checklist","id":"banco","title":"Open a bank account","items":["CPF","Proof of address","Proof of income (e.g. scholarship)","Temporary or permanent visa","Passport or CRNM (or application receipt)"]},{"type":"callout","tone":"info","title":"SIM card","text":"A line can only be activated with a CPF. The main carriers are Vivo, Claro and Tim, with shops in malls. To call abroad, use messaging apps. Brazil code: +55; Pernambuco: 81."},{"type":"checklist","id":"aluguel","title":"Rent a home","items":["Valid passport","CRNM","Residence or work visa","Proof of income (some landlords ask)"]},{"type":"p","text":"Residential neighbourhoods near UFRPE: Dois Irmãos, Várzea, Caxangá, Iputinga and Apipucos."}]'::jsonb, '[{"type":"checklist","id":"banco","title":"Abrir una cuenta bancaria","items":["CPF","Comprovante de residência","Comprovante de renda (bolsa, por exemplo)","Visto temporário ou permanente","Passaporte ou CRNM (ou protocolo do pedido)"]},{"type":"callout","tone":"info","title":"Chip de celular","text":"A linha só é ativada com CPF. As operadoras principais são Vivo, Claro e Tim, com lojas nos shoppings. Para falar com o exterior, prefira aplicativos de mensagem. Código do Brasil: +55; Pernambuco: 81."},{"type":"checklist","id":"aluguel","title":"Alquilar una vivienda","items":["Passaporte válido","CRNM","Visto de residência ou de trabalho","Comprovante de renda (alguns proprietários pedem)"]},{"type":"p","text":"Bairros residenciais próximos à UFRPE: Dois Irmãos, Várzea, Caxangá, Iputinga e Apipucos."}]'::jsonb, '[]'::jsonb, null, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 5),
  ('mobilidade-in', 'documentos', 'mobilidade', 'Mobilidade IN: estudar na UFRPE', 'Incoming mobility: study at UFRPE', 'Movilidad IN: estudiar en la UFRPE', 'Requisitos e documentos para estudantes estrangeiros se candidatarem.', 'Requirements and documents for foreign students to apply.', 'Requisitos y documentos para que estudiantes extranjeros postulen.', '[{"type":"p","text":"Entre em contato antecipadamente com o NINTER/IPÊ e envie sua candidatura digital. Na graduação, é possível cursar até 6 disciplinas de cursos diferentes; na pós-graduação, contate primeiro o Programa (PPG) de interesse."},{"type":"checklist","id":"mobilidade-in","title":"Documentos da candidatura","items":["Comprovante de vínculo com a instituição de origem","Histórico escolar da universidade de origem","Passaporte com visto obtido no Consulado brasileiro","Plano de estudos com equivalência das disciplinas","Seguro saúde","Certificado ou declaração de proficiência em português","Formulário de candidatura do NINTER/IPÊ"]},{"type":"callout","tone":"info","text":"Estudantes de instituições parceiras precisam, no mínimo, de um Memorando de Entendimento (MOU) assinado entre as universidades. Estágios supervisionados de 3 a 6 meses são vinculados a um orientador da UFRPE."}]'::jsonb, '[{"type":"p","text":"Contact NINTER/IPÊ in advance and send your application digitally. Undergraduates may take up to 6 courses from different programs; graduate students should first contact the program (PPG) of interest."},{"type":"checklist","id":"mobilidade-in","title":"Application documents","items":["Proof of enrolment at your home institution","Transcript from your home university","Passport with visa from the Brazilian Consulate","Study plan with course equivalences","Health insurance","Portuguese proficiency certificate or statement","NINTER/IPÊ application form"]},{"type":"callout","tone":"info","text":"Students from partner institutions need at least a signed Memorandum of Understanding (MOU) between the universities. Supervised internships of 3 to 6 months are linked to a UFRPE supervisor."}]'::jsonb, '[{"type":"p","text":"Entre em contato antecipadamente com o NINTER/IPÊ e envie sua candidatura digital. Na graduação, é possível cursar até 6 disciplinas de cursos diferentes; na pós-graduação, contate primeiro o Programa (PPG) de interesse."},{"type":"checklist","id":"mobilidade-in","title":"Documentos de la postulación","items":["Comprovante de vínculo com a instituição de origem","Histórico escolar da universidade de origem","Passaporte com visto obtido no Consulado brasileiro","Plano de estudos com equivalência das disciplinas","Seguro saúde","Certificado ou declaração de proficiência em português","Formulário de candidatura do NINTER/IPÊ"]},{"type":"callout","tone":"info","text":"Estudantes de instituições parceiras precisam, no mínimo, de um Memorando de Entendimento (MOU) assinado entre as universidades. Estágios supervisionados de 3 a 6 meses são vinculados a um orientador da UFRPE."}]'::jsonb, '[{"label":"Guia de Mobilidade IN","url":"https://international.ufrpe.br/mobilidadein"},{"label":"Formulário de candidatura","url":"https://docs.google.com/forms/d/1CJAgP-p6goCS-R23pYx1e7EBrDXN2D6b4bTJ6P7Tpq8/viewform"},{"label":"GCUB — bolsas para estrangeiros","url":"https://www.gcub.org.br"}]'::jsonb, '[{"label":"Incoming Mobility Guide","url":"https://international.ufrpe.br/mobilidadein"},{"label":"Application form","url":"https://docs.google.com/forms/d/1CJAgP-p6goCS-R23pYx1e7EBrDXN2D6b4bTJ6P7Tpq8/viewform"},{"label":"GCUB — scholarships for foreigners","url":"https://www.gcub.org.br"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 6),
  ('mobilidade-out', 'documentos', 'mobilidade', 'Mobilidade OUT e editais', 'Outgoing mobility and calls', 'Movilidad OUT y convocatorias', 'Quem pode participar, programas parceiros e passo a passo para estudar fora.', 'Who can apply, partner programs and step by step to study abroad.', 'Quién puede participar, programas socios y paso a paso para estudiar afuera.', '[{"type":"facts","items":[{"label":"Graduação","value":"Matrícula ativa, 40% a 80% do curso concluído, CR ≥ 7,0 e proficiência no idioma do destino"},{"label":"Pós-graduação","value":"Matrícula ativa, exigências do PPG e proficiência no idioma"},{"label":"Editais","value":"Publicados ao longo do ano no site da UFRPE"}]},{"type":"heading","text":"Programas em parceria"},{"type":"list","items":["GCUB — BRACOL (Colômbia) e BRAMEX (México), com auxílio para alimentação e alojamento","Santander — Bolsas Ibero-Americanas (Portugal, Espanha e América Hispânica)","CAPES — BRAFAGRI (França) para Veterinária, Agronomia, Eng. Agrícola e Ambiental e Zootecnia","Erasmus+ — um ano acadêmico na Europa com bolsa","ELAP — auxílio para universidades canadenses"]},{"type":"heading","text":"Passo a passo (graduação)"},{"type":"steps","items":[{"title":"Comunique o NINTER e seu coordenador de curso"},{"title":"Reúna a documentação","text":"Ofício ao NINTER, plano de trabalho, histórico, carta de aceite, termo de bolsa e carta de intenção (se houver) e comprovante de proficiência."},{"title":"Abra o processo no SIPAC","text":"Envie para processo@ufrpe.br o ofício em PDF e todos os documentos num único PDF, pedindo ao DRCA a matrícula em mobilidade a cada semestre."},{"title":"Envie tudo ao NINTER para registro","text":"mobilidade.ninter@ufrpe.br"},{"title":"Comunique o retorno em até 15 dias","text":"Avise o coordenador e o NINTER e responda ao formulário de experiência. As disciplinas cursadas podem ser aproveitadas no histórico."}]},{"type":"callout","tone":"warning","text":"Só compre passagens depois de receber a carta de aceite e o visto. O passaporte deve valer por todo o período e o seguro saúde é obrigatório no país de destino."}]'::jsonb, '[{"type":"facts","items":[{"label":"Undergraduate","value":"Active enrolment, 40–80% of the program completed, GPA ≥ 7.0 and proficiency in the destination language"},{"label":"Graduate","value":"Active enrolment, program requirements and language proficiency"},{"label":"Calls","value":"Published throughout the year on the UFRPE website"}]},{"type":"heading","text":"Partner programs"},{"type":"list","items":["GCUB — BRACOL (Colombia) and BRAMEX (Mexico), with food and housing allowance","Santander — Ibero-American Scholarships (Portugal, Spain and Hispanic America)","CAPES — BRAFAGRI (France) for Veterinary, Agronomy, Agricultural & Environmental Eng. and Animal Science","Erasmus+ — one academic year in Europe with a scholarship","ELAP — funding for Canadian universities"]},{"type":"heading","text":"Step by step (undergraduate)"},{"type":"steps","items":[{"title":"Inform NINTER and your program coordinator"},{"title":"Gather the documents","text":"Letter to NINTER, study plan, transcript, acceptance letter, scholarship agreement and letter of intent (if any) and proficiency certificate."},{"title":"Open the SIPAC process","text":"Email processo@ufrpe.br the letter as a PDF and all documents in a single PDF, asking DRCA for mobility enrolment each semester."},{"title":"Send everything to NINTER for the record","text":"mobilidade.ninter@ufrpe.br"},{"title":"Report your return within 15 days","text":"Notify your coordinator and NINTER and fill in the experience form. Courses taken abroad may be credited to your transcript."}]},{"type":"callout","tone":"warning","text":"Only buy tickets after receiving the acceptance letter and visa. Your passport must be valid for the whole period and health insurance is mandatory in the destination country."}]'::jsonb, '[{"type":"facts","items":[{"label":"Grado","value":"Matrícula ativa, 40% a 80% do curso concluído, CR ≥ 7,0 e proficiência no idioma do destino"},{"label":"Posgrado","value":"Matrícula ativa, exigências do PPG e proficiência no idioma"},{"label":"Convocatorias","value":"Publicados ao longo do ano no site da UFRPE"}]},{"type":"heading","text":"Programas en alianza"},{"type":"list","items":["GCUB — BRACOL (Colômbia) e BRAMEX (México), com auxílio para alimentação e alojamento","Santander — Bolsas Ibero-Americanas (Portugal, Espanha e América Hispânica)","CAPES — BRAFAGRI (França) para Veterinária, Agronomia, Eng. Agrícola e Ambiental e Zootecnia","Erasmus+ — um ano acadêmico na Europa com bolsa","ELAP — auxílio para universidades canadenses"]},{"type":"heading","text":"Paso a paso (grado)"},{"type":"steps","items":[{"title":"Comunique o NINTER e seu coordenador de curso"},{"title":"Reúna a documentação","text":"Ofício ao NINTER, plano de trabalho, histórico, carta de aceite, termo de bolsa e carta de intenção (se houver) e comprovante de proficiência."},{"title":"Abra o processo no SIPAC","text":"Envie para processo@ufrpe.br o ofício em PDF e todos os documentos num único PDF, pedindo ao DRCA a matrícula em mobilidade a cada semestre."},{"title":"Envie tudo ao NINTER para registro","text":"mobilidade.ninter@ufrpe.br"},{"title":"Comunique o retorno em até 15 dias","text":"Avise o coordenador e o NINTER e responda ao formulário de experiência. As disciplinas cursadas podem ser aproveitadas no histórico."}]},{"type":"callout","tone":"warning","text":"Só compre passagens depois de receber a carta de aceite e o visto. O passaporte deve valer por todo o período e o seguro saúde é obrigatório no país de destino."}]'::jsonb, '[{"label":"Guia de Mobilidade OUT","url":"https://international.ufrpe.br/mobilidadeout"},{"label":"Editais no portal da UFRPE","url":"https://www.ufrpe.br"},{"label":"Formulário de experiência em mobilidade","url":"https://docs.google.com/forms/d/1lYMpfyFHrSufYu5ayeCq0vrQh6NCFZ42MKhWfMHAUvk/viewform"}]'::jsonb, '[{"label":"Outgoing Mobility Guide","url":"https://international.ufrpe.br/mobilidadeout"},{"label":"Calls on the UFRPE website","url":"https://www.ufrpe.br"},{"label":"Mobility experience form","url":"https://docs.google.com/forms/d/1lYMpfyFHrSufYu5ayeCq0vrQh6NCFZ42MKhWfMHAUvk/viewform"}]'::jsonb, null, 'Guia de Mobilidade Acadêmica OUT · NINTER/IPÊ', 'Outgoing Mobility Guide · NINTER/IPÊ', 'Guía de Movilidad Académica OUT · NINTER/IPÊ', null, 7),
  ('primeira-semana', 'calouro', null, 'Primeira semana no campus', 'First week on campus', 'Primera semana en el campus', 'O que fazer assim que chegar à UFRPE.', 'What to do as soon as you arrive at UFRPE.', 'Qué hacer en cuanto llegues a la UFRPE.', '[{"type":"steps","items":[{"title":"Chegue alguns dias antes das aulas","text":"Assim dá tempo de resolver documentação, matrícula e moradia e participar da recepção de estudantes estrangeiros."},{"title":"Confirme sua matrícula","text":"Graduação: com o NINTER/IPÊ. Pós-graduação: na secretaria do seu Programa, em horário de atendimento presencial."},{"title":"Ative Wi-Fi e SIGAA","text":"Com CPF e matrícula, cadastre login e senha seguindo a Central de Ajuda da UFRPE."},{"title":"Localize os lugares essenciais no mapa","text":"Seu departamento, a Biblioteca Central, o Restaurante Universitário e o Prédio Central."}]}]'::jsonb, '[{"type":"steps","items":[{"title":"Arrive a few days before classes","text":"This gives you time to sort out documents, enrolment and housing and attend the welcome session for international students."},{"title":"Confirm your enrolment","text":"Undergraduate: with NINTER/IPÊ. Graduate: at your program office during in-person hours."},{"title":"Activate Wi-Fi and SIGAA","text":"With your CPF and enrolment, set up your login following UFRPE''s Help Center."},{"title":"Find the key places on the map","text":"Your department, the Central Library, the University Restaurant and the Central Building."}]}]'::jsonb, '[{"type":"steps","items":[{"title":"Llega unos días antes de las clases","text":"Assim dá tempo de resolver documentação, matrícula e moradia e participar da recepção de estudantes estrangeiros."},{"title":"Confirma tu matrícula","text":"Graduação: com o NINTER/IPÊ. Pós-graduação: na secretaria do seu Programa, em horário de atendimento presencial."},{"title":"Activa el Wi-Fi y el SIGAA","text":"Com CPF e matrícula, cadastre login e senha seguindo a Central de Ajuda da UFRPE."},{"title":"Ubica los lugares clave en el mapa","text":"Seu departamento, a Biblioteca Central, o Restaurante Universitário e o Prédio Central."}]}]'::jsonb, '[{"label":"Wi-Fi UFRPE — Central de Ajuda","url":"https://ajuda.ufrpe.br/sections/wifi-ufrpe"},{"label":"SIGAA","url":"https://sigs.ufrpe.br/sigaa/verTelaLogin.do"}]'::jsonb, '[{"label":"UFRPE Wi-Fi — Help Center","url":"https://ajuda.ufrpe.br/sections/wifi-ufrpe"},{"label":"SIGAA","url":"https://sigs.ufrpe.br/sigaa/verTelaLogin.do"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', (select id from public.places where slug = 'reitoria'), 0),
  ('vida-academica-regras', 'calouro', null, 'Calendário, créditos e notas', 'Calendar, credits and grades', 'Calendario, créditos y notas', 'Como funcionam semestres, frequência e aprovação.', 'How semesters, attendance and passing work.', 'Cómo funcionan semestres, asistencia y aprobación.', '[{"type":"facts","items":[{"label":"Ano letivo","value":"Fevereiro a dezembro, em dois semestres, com 3 a 5 semanas de férias entre eles"},{"label":"Créditos","value":"1 crédito = 15 horas-aula; a maioria das disciplinas tem 4 créditos (60 h)"},{"label":"Frequência","value":"Mínimo de 75% das aulas"},{"label":"Graduação","value":"Média ≥ 7,0 aprova direto; entre 3,0 e 7,0 faz exame final e precisa de média final ≥ 5,0"},{"label":"Pós-graduação","value":"Nota ≥ 6,0 aprova; é possível repetir a disciplina uma única vez"}]}]'::jsonb, '[{"type":"facts","items":[{"label":"Academic year","value":"February to December, in two semesters, with 3–5 weeks of break in between"},{"label":"Credits","value":"1 credit = 15 class hours; most courses have 4 credits (60 h)"},{"label":"Attendance","value":"At least 75% of classes"},{"label":"Undergraduate","value":"Average ≥ 7.0 passes; between 3.0 and 7.0 takes a final exam and needs a final average ≥ 5.0"},{"label":"Graduate","value":"Grade ≥ 6.0 passes; a course may be repeated only once"}]}]'::jsonb, '[{"type":"facts","items":[{"label":"Año lectivo","value":"Fevereiro a dezembro, em dois semestres, com 3 a 5 semanas de férias entre eles"},{"label":"Créditos","value":"1 crédito = 15 horas-aula; a maioria das disciplinas tem 4 créditos (60 h)"},{"label":"Asistencia","value":"Mínimo de 75% das aulas"},{"label":"Grado","value":"Média ≥ 7,0 aprova direto; entre 3,0 e 7,0 faz exame final e precisa de média final ≥ 5,0"},{"label":"Posgrado","value":"Nota ≥ 6,0 aprova; é possível repetir a disciplina uma única vez"}]}]'::jsonb, '[{"label":"Calendário acadêmico (DRCA)","url":"http://drca.ufrpe.br/"}]'::jsonb, '[{"label":"Academic calendar (DRCA)","url":"http://drca.ufrpe.br/"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', null, 1),
  ('beneficios', 'calouro', null, 'RU, biblioteca e outros benefícios', 'Canteen, library and other benefits', 'Comedor, biblioteca y otros beneficios', 'Restaurante Universitário, bibliotecas, saúde, esportes e residência.', 'University Restaurant, libraries, health, sports and student housing.', 'Restaurante Universitario, bibliotecas, salud, deportes y residencia.', '[{"type":"facts","items":[{"label":"Restaurante Universitário","value":"Seg. a sex. · almoço 10h30–14h (R$ 3,50) · jantar 16h30–19h (R$ 3,00). Acesso com comprovante de matrícula."},{"label":"Biblioteca","value":"Cadastro com CPF, CRNM, comprovante de residência e de matrícula"},{"label":"Saúde (DQV)","value":"Passaporte, 2 fotos 3x4 e comprovante de matrícula · (81) 3320-6152"},{"label":"Esportes","value":"Atletismo, vôlei, basquete, handebol, musculação, natação, futsal, ioga e dança · (81) 3320-5445"},{"label":"Residência","value":"Vagas para estrangeiros todo semestre, mediante pedido prévio ao NINTER"}]},{"type":"callout","tone":"tip","title":"Português como Língua Estrangeira","text":"Cursos gratuitos todo semestre pela Rede Andifes-IsF e pelo Núcleo de Idiomas (NID). Fale com nid@ufrpe.br."}]'::jsonb, '[{"type":"facts","items":[{"label":"University Restaurant","value":"Mon–Fri · lunch 10:30am–2pm (R$3.50) · dinner 4:30pm–7pm (R$3.00). Access with proof of enrolment."},{"label":"Library","value":"Register with CPF, CRNM, proof of address and enrolment"},{"label":"Health (DQV)","value":"Passport, two 3x4 photos and proof of enrolment · (81) 3320-6152"},{"label":"Sports","value":"Athletics, volleyball, basketball, handball, gym, swimming, futsal, yoga and dance · (81) 3320-5445"},{"label":"Student housing","value":"Places for international students every semester, by prior request to NINTER"}]},{"type":"callout","tone":"tip","title":"Portuguese as a Foreign Language","text":"Free courses every semester through the Andifes-IsF Network and the Language Center (NID). Contact nid@ufrpe.br."}]'::jsonb, '[{"type":"facts","items":[{"label":"Restaurante Universitario","value":"Seg. a sex. · almoço 10h30–14h (R$ 3,50) · jantar 16h30–19h (R$ 3,00). Acesso com comprovante de matrícula."},{"label":"Biblioteca","value":"Cadastro com CPF, CRNM, comprovante de residência e de matrícula"},{"label":"Salud (DQV)","value":"Passaporte, 2 fotos 3x4 e comprovante de matrícula · (81) 3320-6152"},{"label":"Deportes","value":"Atletismo, vôlei, basquete, handebol, musculação, natação, futsal, ioga e dança · (81) 3320-5445"},{"label":"Residencia","value":"Vagas para estrangeiros todo semestre, mediante pedido prévio ao NINTER"}]},{"type":"callout","tone":"tip","title":"Portugués como Lengua Extranjera","text":"Cursos gratuitos todo semestre pela Rede Andifes-IsF e pelo Núcleo de Idiomas (NID). Fale com nid@ufrpe.br."}]'::jsonb, '[{"label":"Cardápio do RU","url":"/cardapio"},{"label":"Bibliotecas — guia do usuário","url":"http://www.sib.ufrpe.br/guia-do-usuario#cadastro"}]'::jsonb, '[{"label":"Canteen menu","url":"/cardapio"},{"label":"Libraries — user guide","url":"http://www.sib.ufrpe.br/guia-do-usuario#cadastro"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', (select id from public.places where slug = 'ru'), 2),
  ('conheca-recife', 'recife', null, 'Conheça Recife', 'Discover Recife', 'Conoce Recife', 'Vídeos e fotos oficiais da cidade que vai ser sua casa.', 'Official videos and photos of the city that will be your home.', 'Videos y fotos oficiales de la ciudad que será tu casa.', '[{"type":"p","text":"Recife é a capital de Pernambuco, conhecida pelos rios e pontes, pelo frevo e maracatu, pelo Carnaval e por praias como Boa Viagem. O campus Sede da UFRPE fica no bairro de Dois Irmãos, na zona norte."},{"type":"video","title":"Recife é pra ficar","credit":"Prefeitura do Recife","driveId":"1yC72NgqCKSAK3zH2uVvw5pK1LroF4PJG"},{"type":"video","title":"Vídeo institucional de Recife","credit":"Recife Convention & Visitors Bureau","driveId":"17Lac3rPYxyFdJ2a-XsFuI5RQmBuK3mHD"},{"type":"gallery","title":"Fotos oficiais de Recife","credit":"Sol Pulquério / Prefeitura do Recife","folderId":"1gND0uVw9b-f2jdQSu03jMvCSl8d5tdoO","url":"https://drive.google.com/drive/folders/1gND0uVw9b-f2jdQSu03jMvCSl8d5tdoO","embed":true},{"type":"gallery","title":"Mais fotos de Recife","credit":"Dondinh","folderId":"1-v2QP-AOc_uL1g6re50fjRhLKYF26G-s","url":"https://drive.google.com/drive/folders/1-v2QP-AOc_uL1g6re50fjRhLKYF26G-s","embed":false}]'::jsonb, '[{"type":"p","text":"Recife is the capital of Pernambuco, known for its rivers and bridges, frevo and maracatu, Carnival and beaches such as Boa Viagem. UFRPE''s main campus is in the Dois Irmãos neighbourhood, in the north of the city."},{"type":"video","title":"Recife is a place to stay","credit":"Prefeitura do Recife","driveId":"1yC72NgqCKSAK3zH2uVvw5pK1LroF4PJG"},{"type":"video","title":"Recife institutional video","credit":"Recife Convention & Visitors Bureau","driveId":"17Lac3rPYxyFdJ2a-XsFuI5RQmBuK3mHD"},{"type":"gallery","title":"Official photos of Recife","credit":"Sol Pulquério / Prefeitura do Recife","folderId":"1gND0uVw9b-f2jdQSu03jMvCSl8d5tdoO","url":"https://drive.google.com/drive/folders/1gND0uVw9b-f2jdQSu03jMvCSl8d5tdoO","embed":true},{"type":"gallery","title":"More photos of Recife","credit":"Dondinh","folderId":"1-v2QP-AOc_uL1g6re50fjRhLKYF26G-s","url":"https://drive.google.com/drive/folders/1-v2QP-AOc_uL1g6re50fjRhLKYF26G-s","embed":false}]'::jsonb, '[{"type":"p","text":"Recife es la capital de Pernambuco, conocida por sus ríos y puentes, el frevo y el maracatu, el Carnaval y playas como Boa Viagem. El campus Sede de la UFRPE está en el barrio de Dois Irmãos, en la zona norte."},{"type":"video","title":"Recife es para quedarse","credit":"Prefeitura do Recife","driveId":"1yC72NgqCKSAK3zH2uVvw5pK1LroF4PJG"},{"type":"video","title":"Video institucional de Recife","credit":"Recife Convention & Visitors Bureau","driveId":"17Lac3rPYxyFdJ2a-XsFuI5RQmBuK3mHD"},{"type":"gallery","title":"Fotos oficiales de Recife","credit":"Sol Pulquério / Prefeitura do Recife","folderId":"1gND0uVw9b-f2jdQSu03jMvCSl8d5tdoO","url":"https://drive.google.com/drive/folders/1gND0uVw9b-f2jdQSu03jMvCSl8d5tdoO","embed":true},{"type":"gallery","title":"Más fotos de Recife","credit":"Dondinh","folderId":"1-v2QP-AOc_uL1g6re50fjRhLKYF26G-s","url":"https://drive.google.com/drive/folders/1-v2QP-AOc_uL1g6re50fjRhLKYF26G-s","embed":false}]'::jsonb, '[]'::jsonb, null, null, 'Prefeitura do Recife e Recife Convention & Visitors Bureau', 'Recife City Hall and Recife Convention & Visitors Bureau', 'Alcaldía de Recife y Recife Convention & Visitors Bureau', null, 0),
  ('chegada-transporte', 'recife', null, 'Chegada e transporte', 'Arrival and transport', 'Llegada y transporte', 'Do aeroporto ao campus e como usar ônibus e BRT.', 'From the airport to campus and how to use buses and BRT.', 'Del aeropuerto al campus y cómo usar autobuses y BRT.', '[{"type":"steps","items":[{"title":"Reserve hospedagem antes de chegar","text":"Mesmo que provisória."},{"title":"Saia do aeroporto de táxi registrado ou aplicativo","text":"Dá para pagar o traslado antes, na área de bagagens, em dinheiro ou cartão. O Uber também é muito usado."},{"title":"Use o VEM no transporte público","text":"Há paradas em frente à Portaria Principal. Com o VEM estudante a passagem é mais barata."}]}]'::jsonb, '[{"type":"steps","items":[{"title":"Book accommodation before arriving","text":"Even if temporary."},{"title":"Leave the airport by registered taxi or app","text":"You can prepay the ride in the baggage area, in cash or by card. Uber is also widely used."},{"title":"Use the VEM card on public transport","text":"There are stops in front of the Main Gate. With the student VEM card fares are cheaper."}]}]'::jsonb, '[{"type":"steps","items":[{"title":"Reserva alojamiento antes de llegar","text":"Mesmo que provisória."},{"title":"Sal del aeropuerto en taxi registrado o aplicación","text":"Dá para pagar o traslado antes, na área de bagagens, em dinheiro ou cartão. O Uber também é muito usado."},{"title":"Usa la VEM en el transporte público","text":"Há paradas em frente à Portaria Principal. Com o VEM estudante a passagem é mais barata."}]}]'::jsonb, '[{"label":"Grande Recife Consórcio de Transporte","url":"https://www.granderecife.pe.gov.br"}]'::jsonb, '[{"label":"Grande Recife Transport Consortium","url":"https://www.granderecife.pe.gov.br"}]'::jsonb, null, 'Guia do Estudante Internacional · NINTER/IPÊ', 'International Student''s Guide · NINTER/IPÊ', 'Guía del Estudiante Internacional · NINTER/IPÊ', (select id from public.places where slug = 'portaria-principal'), 1),
  ('seguranca', 'recife', null, 'Segurança e leis', 'Safety and laws', 'Seguridad y leyes', 'Cuidados no dia a dia e números de emergência gratuitos.', 'Everyday precautions and free emergency numbers.', 'Cuidados diarios y números de emergencia gratuitos.', '[{"type":"list","items":["evite exibir objetos de valor em locais públicos;","fique atento(a) em áreas movimentadas;","use transportes oficiais e aplicativos confiáveis;","guarde documentos importantes em local seguro."]},{"type":"callout","tone":"info","text":"Todos os estrangeiros devem cumprir as leis brasileiras, inclusive normas migratórias e de trânsito. O desconhecimento da lei não isenta de responsabilidade. Polícia (190), SAMU (192) e Bombeiros (193) são gratuitos."}]'::jsonb, '[{"type":"list","items":["avoid displaying valuables in public places;","stay aware in crowded areas;","use official transport and trusted apps;","keep important documents in a safe place."]},{"type":"callout","tone":"info","text":"All foreigners must comply with Brazilian law, including immigration and traffic rules. Ignorance of the law is no excuse. Police (190), SAMU (192) and Fire Department (193) are free of charge."}]'::jsonb, null, '[]'::jsonb, null, null, 'Cartilha de Acolhimento · NINTER/PRPG UFRPE', 'Welcome Booklet · NINTER/PRPG UFRPE', 'Cartilla de Acogida · NINTER/PRPG UFRPE', null, 2);
